 * @name scwin.X_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.X_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin X_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        swapImage('X', '23');await scwin.fnSearchBeginIndex(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst90001.X_onclick' }); }
};

