/**
 * @method
 * @name scwin.reflectCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reflectCorpName = function () {
    /* sdd-asis-lifecycle:begin reflectCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let corpNameTmp = $c.util.getComponent('ipt_corpNameTmp').getValue();
    corpNameTmp = encodeURI(corpNameTmp);
    $c.util.getComponent('ipt_corpName').setValue(corpNameTmp);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("pageIndex", "1");
    $c.util.getComponent('ipt_beginIndex').setValue("");
    clearBtnImage();
    scwin.reflectCorpName();
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchBeginIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchBeginIndex = async function () {
    /* sdd-asis-lifecycle:begin fnSearchBeginIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_corpName').setValue("");
    $c.util.getComponent('ipt_corpNameTmp').setValue("");
    await scwin.tx_fnSearchBeginIndex_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


